BEGIN;
CREATE TABLE tracking.clicks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenant.tenants(id) ON DELETE CASCADE, user_id uuid REFERENCES identity.users(id), offer_id uuid NOT NULL REFERENCES affiliate.offers(id), provider_click_id text, occurred_at timestamptz NOT NULL DEFAULT now(), metadata jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE tracking.conversions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenant.tenants(id) ON DELETE CASCADE, provider_id uuid NOT NULL REFERENCES core.providers(id), external_id text NOT NULL, click_id uuid REFERENCES tracking.clicks(id), user_id uuid REFERENCES identity.users(id), offer_id uuid REFERENCES affiliate.offers(id), status tracking.conversion_status NOT NULL DEFAULT 'RECEIVED', gross_amount numeric(20,8) CHECK(gross_amount IS NULL OR gross_amount>=0), currency char(3), correlation_id uuid NOT NULL DEFAULT gen_random_uuid(), received_at timestamptz NOT NULL DEFAULT now(), verified_at timestamptz, UNIQUE(tenant_id,provider_id,external_id));
CREATE TABLE tracking.raw_webhooks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid REFERENCES tenant.tenants(id), provider_id uuid REFERENCES core.providers(id), external_event_id text, signature_valid boolean NOT NULL DEFAULT false, headers jsonb NOT NULL DEFAULT '{}'::jsonb, payload jsonb NOT NULL, received_at timestamptz NOT NULL DEFAULT now(), UNIQUE(provider_id,external_event_id));
COMMIT;
